Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
netfilter: conntrack_irc: fix possible out-of-bounds read

When parsing fails after we've matched the command string we
should bail out instead of trying to match a different command.

This helper should be deprecated, given prevalence of TLS I doubt it has
any relevance in 2026.

Fixes: 869f37d8e48f ("[NETFILTER]: nf_conntrack/nf_nat: add IRC helper port")
Closes: https://sashiko.dev/#/patchset/20260525182924.28456-1-fw%40strlen.de
Signed-off-by: Florian Westphal <fw@strlen.de>
Reviewed-by: Fernando Fernandez Mancera <fmancera@suse.de>
Signed-off-by: Pablo Neira Ayuso <pablo@netfilter.org>

Here is the root cause:
After matching a command string, if parsing fails (e.g., parse_dcc failure or forged DCC detection), the loop incorrectly continues to the next iteration instead of exiting, which can cause an out-of-bounds read because the data pointer or limits may become invalid or the loop scans beyond the buffer.

Here is the patch:

 static int help(struct sk_buff *skb, unsigned int protoff,
 		struct nf_conn *ct, enum ip_conntrack_info ctinfo)
 {
 	unsigned int dataoff;
 	const struct iphdr *iph;
 	const struct tcphdr *th;
 	struct tcphdr _tcph;
 	const char *data_limit;
 	char *data, *ib_ptr;
 	int dir = CTINFO2DIR(ctinfo);
 	struct nf_conntrack_expect *exp;
 	struct nf_conntrack_tuple *tuple;
 	__be32 dcc_ip;
 	u_int16_t dcc_port;
 	__be16 port;
 	int i, ret = NF_ACCEPT;
 	char *addr_beg_p, *addr_end_p;
 	nf_nat_irc_hook_fn *nf_nat_irc;
 	unsigned int datalen;

 	/* If packet is coming from IRC server */
 	if (dir == IP_CT_DIR_REPLY)
 		return NF_ACCEPT;

 	/* Until there's been traffic both ways, don't look in packets. */
 	if (ctinfo != IP_CT_ESTABLISHED && ctinfo != IP_CT_ESTABLISHED_REPLY)
 		return NF_ACCEPT;

 	/* Not a full tcp header? */
 	th = skb_header_pointer(skb, protoff, sizeof(_tcph), &_tcph);
 	if (th == NULL)
 		return NF_ACCEPT;

 	/* No data? */
 	dataoff = protoff + th->doff*4;
 	if (dataoff >= skb->len)
 		return NF_ACCEPT;

 	datalen = skb->len - dataoff;
 	if (datalen > MAX_SEARCH_SIZE)
 		datalen = MAX_SEARCH_SIZE;

 	spin_lock_bh(&irc_buffer_lock);
 	ib_ptr = skb_header_pointer(skb, dataoff, datalen,
 				    irc_buffer);
 	if (!ib_ptr) {
 		spin_unlock_bh(&irc_buffer_lock);
 		return NF_ACCEPT;
 	}

 	data = ib_ptr;
 	data_limit = ib_ptr + datalen;

 	/* Skip any whitespace */
 	while (data < data_limit - 10) {
 		if (*data == ' ' || *data == '\r' || *data == '\n')
 			data++;
 		else
 			break;
 	}

 	/* strlen("PRIVMSG x ")=10 */
 	if (data < data_limit - 10) {
 		if (strncasecmp("PRIVMSG ", data, 8))
 			goto out;
 		data += 8;
 	}

 	/* strlen(" :\1DCC SENT t AAAAAAAA P\1\n")=26
 	 * 7+MINMATCHLEN+strlen("t AAAAAAAA P\1\n")=26
 	 */
 	while (data < data_limit - (21 + MINMATCHLEN)) {
 		/* Find first " :", the start of message */
 		if (memcmp(data, " :", 2)) {
 			data++;
 			continue;
 		}
 		data += 2;

 		/* then check that place only for the DCC command */
 		if (memcmp(data, "\1DCC ", 5))
 			goto out;
 		data += 5;
 		/* we have at least (21+MINMATCHLEN)-(2+5) bytes valid data left */

 		iph = ip_hdr(skb);
 		pr_debug("DCC found in master %pI4:%u %pI4:%u\n",
 			 &iph->saddr, ntohs(th->source),
 			 &iph->daddr, ntohs(th->dest));

 		for (i = 0; i < ARRAY_SIZE(dccprotos); i++) {
 			if (memcmp(data, dccprotos[i], strlen(dccprotos[i]))) {
 				/* no match */
 				continue;
 			}
 			data += strlen(dccprotos[i]);
 			pr_debug("DCC %s detected\n", dccprotos[i]);

 			/* we have at least
 			 * (21+MINMATCHLEN)-7-dccprotos[i].matchlen bytes valid
 			 * data left (== 14/13 bytes) */
 			if (parse_dcc(data, data_limit, &dcc_ip,
 				       &dcc_port, &addr_beg_p, &addr_end_p)) {
 				pr_debug("unable to parse dcc command\n");
-				continue;
+				goto out;
 			}

 			pr_debug("DCC bound ip/port: %pI4:%u\n",
 				 &dcc_ip, dcc_port);

 			/* dcc_ip can be the internal OR external (NAT'ed) IP */
 			tuple = &ct->tuplehash[dir].tuple;
 			if ((tuple->src.u3.ip != dcc_ip &&
 			     ct->tuplehash[!dir].tuple.dst.u3.ip != dcc_ip) ||
 			    dcc_port == 0) {
 				net_warn_ratelimited("Forged DCC command from %pI4: %pI4:%u\n",
 						     &tuple->src.u3.ip,
 						     &dcc_ip, dcc_port);
-				continue;
+				goto out;
 			}

 			exp = nf_ct_expect_alloc(ct);
 			if (exp == NULL) {
 				nf_ct_helper_log(skb, ct,
 						 "cannot alloc expectation");
 				ret = NF_DROP;
 				goto out;
 			}
 			tuple = &ct->tuplehash[!dir].tuple;
 			port = htons(dcc_port);
 			nf_ct_expect_init(exp, NF_CT_EXPECT_CLASS_DEFAULT,
 					  tuple->src.l3num,
 					  NULL, &tuple->dst.u3,
 					  IPPROTO_TCP, NULL, &port);

 			nf_nat_irc = rcu_dereference(nf_nat_irc_hook);
 			if (nf_nat_irc && ct->status & IPS_NAT_MASK)
 				ret = nf_nat_irc(skb, ctinfo, protoff,
 						 addr_beg_p - ib_ptr,
 						 addr_end_p - addr_beg_p,
 						 exp);
 			else if (nf_ct_expect_related(exp, 0) != 0) {
 				nf_ct_helper_log(skb, ct,
 						 "cannot add expectation");
 				ret = NF_DROP;
 			}
 			nf_ct_expect_put(exp);
 			goto out;
 		}
 	}
  out:
 	spin_unlock_bh(&irc_buffer_lock);
 	return ret;
 }



